const { useState } = React;

function Panel() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div>
      <button id="toggle" onClick={() => setIsOpen(!isOpen)}>
        Toggle
      </button>
      {isOpen && <p id="panel">Panel content</p>}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<Panel />);
